from typing import Annotated, Any, Literal
from pydantic import BaseModel, Field
from fastapi import FastAPI, Body
from fastapi.params import Discriminator, Tag
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()

@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_discriminated_union_body():
    # This should work if it's recognized as a body field
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5})
    assert response.status_code == 200
    assert response.json() == {"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5}

    response = client.post("/dessert", json={"filling": "pumpkin", "time_to_cook": 60, "num_ingredients": 10})
    assert response.status_code == 200
    assert response.json() == {"filling": "pumpkin", "time_to_cook": 60, "num_ingredients": 10}

if __name__ == "__main__":
    try:
        test_discriminated_union_body()
        print("Test passed!")
