def test_discriminated_union_body():
    # This should work if it's recognized as a body field
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5})
    print(f"Response status: {response.status_code}")
    print(f"Response body: {response.text}")
    assert response.status_code == 200
    assert response.json() == {"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5}

    response = client.post("/dessert", json={"filling": "pumpkin", "time_to_cook": 60, "num_ingredients": 10})
    print(f"Response status: {response.status_code}")
    print(f"Response body: {response.text}")
    assert response.status_code == 200
    assert response.json() == {"filling": "pumpkin", "time_to_cook": 60, "num_ingredients": 10}

if __name__ == "__main__":
    try:
        test_discriminated_union_body()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

